import User from "./User";
export default class UserMapper {
    static fromJSON(json) {
        const data = JSON.parse(json);
        const user = new User();
        Object.assign(user, data);
        console.log(user);
        return user;
    }
    static toJSON(user) {
        console.log(JSON.stringify(user));
        return JSON.stringify(user);
    }
}
